sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') return;

    var name = g_form.getValue('name');
    var sysId = g_form.getUniqueValue();

    var ga = new GlideAjax('CheckDuplicateBase');
    ga.addParam('sysparm_name', 'checkDuplicateName');
    ga.addParam('sysparm_name_value', name);
    ga.addParam('sysparm_sys_id', sysId);

    ga.getXMLAnswer(function(response) {
        g_form.hideFieldMsg('name');

        if (response === 'DUPLICATE_NAME') {
			g_form.setValue('name','');
            g_form.showFieldMsg('name', 'A base with this name already exists.', 'error');
        }
    });
}
